#!/bin/sh
# SPDX-License-Identifier: GPL-3.0-only
# Denormals are flushed by the CPU mode bench.cpp sets, so -ftz 0. Regenerate gen/*.cpp from dsp/*.dsp (Faust 2.70). The generated files are committed so CI needs no Faust.
set -e
cd "$(dirname "$0")"
for f in dsp/*.dsp; do
  n=$(basename "$f" .dsp)
  faust -single -ftz 0 -cn "P_$n" -I dsp "$f" -o "gen/$n.inc"
  { echo "// Generated by Faust from dsp/$n.dsp (see gen.sh); GPL-3.0-only like its source."
    echo '#include "../faust_min.h"'
    cat "gen/$n.inc"
    echo "dsp* make_$n() { return new P_$n(); }"; } > "gen/$n.cpp"
  rm "gen/$n.inc"
done
